"Service","name":"Homeowner Claim Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/homeowner-claim-appraiser/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Claim Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hail & Roof Damage Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/hail-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Claim Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/wind-tornado-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load & Ice Dam Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/snow-load-ice-dam-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Burst Pipe Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/water-pipe-burst-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Loss Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/fire-smoke-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Claim Appraisal","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/wildfire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Services","url":"https://coloradoinsuranceappraiser.com/colorado-claim-appraisal/umpire-neutral-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Hail damage","Wildfire claims","Xactimate estimating","Umpire services"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://coloradoinsuranceappraiser.com/#website","url":"https://coloradoinsuranceappraiser.com/","name":"Colorado Insurance Appraiser","publisher":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://coloradoinsuranceappraiser.com/resources/faq/#webpage","url":"https://coloradoinsuranceappraiser.com/resources/faq/","name":"Insurance Appraisal FAQ | Colorado Claim Questions","description":"Colorado insurance appraisal FAQ by topic: how the process works, costs and timing, hail and wildfire claims, and Colorado rules to know.","inLanguage":"en-US","isPartOf":{"@id":"https://coloradoinsuranceappraiser.com/#website"},"about":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"publisher":{"@id":"https://coloradoinsuranceappraiser.com/#business"},"dateModified":"2026-11-18","breadcrumb":{"@id":"https://coloradoinsuranceappraiser.com/resources/faq/#breadcrumb"},"primaryImageOfPage":{"@id":"https://coloradoinsuranceappraiser.com/resources/faq/#primaryimage"},"image":{"@id":"https://coloradoinsuranceappraiser.com/resources/faq/#primaryimage"},"mainEntity":{"@id":"https://coloradoinsuranceappraiser.com/resources/faq/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://coloradoinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Resources","item":"https://coloradoinsuranceappraiser.com/resources/"},{"@type":"ListItem","position":3,"name":"FAQ","item":"https://coloradoinsuranceappraiser.com/resources/faq/"}],"@id":"https://coloradoinsuranceappraiser.com/resources/faq/#breadcrumb"},{"@type":"ImageObject","@id":"https://coloradoinsuranceappraiser.com/resources/faq/#primaryimage","url":"https://coloradoinsuranceappraiser.com/assets/img/photos/interior.webp","contentUrl":"https://coloradoinsuranceappraiser.com/assets/img/photos/interior.webp","width":1200,"height":800,"caption":"Bright living room with a sofa, rug and wood floors"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process in most property policies for resolving disagreements about the amount of a covered loss. Each side names an appraiser, the appraisers choose an umpire, and an award signed by two of the three sets the amount."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Usually either party — you or the insurer — can demand it in writing once you disagree on the amount of loss. Check your policy for any conditions that must be met first."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"Not exactly. Appraisal is narrower: it focuses on valuing the loss and is usually less formal than arbitration, with no hearings in the courtroom sense."}},{"@type":"Question","name":"Can I be my own appraiser?","acceptedAnswer":{"@type":"Answer","text":"Most policies require a competent and impartial appraiser, which effectively rules out the policyholder. Hiring an experienced independent appraiser is the norm."}},{"@type":"Question","name":"Does the insurer’s appraiser work for the insurer?","acceptedAnswer":{"@type":"Answer","text":"The insurer selects and pays its appraiser, just as you select and pay yours. Both are expected to be impartial under most policy wording."}},{"@type":"Question","name":"How much does an appraiser cost?","acceptedAnswer":{"@type":"Answer","text":"Fee arrangements vary — flat fees, hourly rates or a percentage of the increase. Whatever the basis, get it in writing before work starts. Umpire fees are usually split."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Many residential files resolve in two to three months after both appraisers are named. Large commercial, wildfire or contents-heavy claims can take longer."}},{"@type":"Question","name":"Is there a deadline to demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies set one, and the policy’s suit-limitation clause still runs. Read your policy and calendar the dates with our timeline builder."}},{"@type":"Question","name":"Is the award paid right away?","acceptedAnswer":{"@type":"Answer","text":"Payment terms depend on the policy. The insurer pays the award less the deductible and prior payments; recoverable depreciation usually follows once repairs are done."}},{"@type":"Question","name":"When is a gap too small for appraisal?","acceptedAnswer":{"@type":"Answer","text":"When fees would consume most of the increase. As a rough guide, gaps under about 10% or a few thousand dollars are often better handled with a documented supplement request."}},{"@type":"Question","name":"Can appraisal decide whether my roof should be replaced?","acceptedAnswer":{"@type":"Answer","text":"Appraisal values the cost to repair or replace covered damage, so repair-versus-replace disputes are often part of it. Coverage questions, such as cosmetic exclusions, may not be."}},{"@type":"Question","name":"Does appraisal work for wildfire total losses?","acceptedAnswer":{"@type":"Answer","text":"Yes, for disputes about the cost to rebuild, debris removal or contents values within your limits. It can’t increase the limits themselves."}},{"@type":"Question","name":"What about smoke damage to a house that didn’t burn?","acceptedAnswer":{"@type":"Answer","text":"Smoke and ash cleaning or replacement disputes are a common appraisal topic, provided the insurer has accepted that a covered loss occurred."}},{"@type":"Question","name":"Can I use appraisal for a frozen-pipe claim?","acceptedAnswer":{"@type":"Answer","text":"If coverage is accepted, yes. Freezing and vacancy exclusions are coverage questions that may need to be resolved first."}},{"@type":"Question","name":"Does appraisal apply to my car?","acceptedAnswer":{"@type":"Answer","text":"Some auto policies have appraisal clauses, but our work focuses on homes and commercial buildings."}},{"@type":"Question","name":"Who regulates insurers in Colorado?","acceptedAnswer":{"@type":"Answer","text":"The Colorado Division of Insurance, part of the Department of Regulatory Agencies (DORA). It licenses insurers and adjusters and accepts consumer complaints."}},{"@type":"Question","name":"What is the Colorado FAIR Plan?","acceptedAnswer":{"@type":"Answer","text":"A last-resort property insurance program created by the legislature in 2023 for owners who can’t find coverage in the regular market, particularly in high-wildfire-risk areas. It began offering policies in 2025."}},{"@type":"Question","name":"Does Colorado have a bad-faith law?","acceptedAnswer":{"@type":"Answer","text":"Yes. Colorado statutes address unreasonable delay or denial of covered benefits, alongside common-law bad-faith claims. Those are legal matters for an attorney, not an appraisal panel."}},{"@type":"Question","name":"Can my roofer pay my deductible?","acceptedAnswer":{"@type":"Answer","text":"No. Colorado law prohibits roofing contractors from paying, waiving or rebating a homeowner’s insurance deductible."}},{"@type":"Question","name":"Who appoints an umpire if the appraisers can’t agree?","acceptedAnswer":{"@type":"Answer","text":"Under typical policy language, a court of record in the county where the property sits — in Colorado, usually the district court."}}],"@id":"https://coloradoinsuranceappraiser.com/resources/faq/#faq"}]}</script>
</head>
